//! A small task tracker.

use std::env;
use std::fs;

/// Priority given to a task nobody set a priority on.
const DEFAULT_PRIORITY: u8 = 5;

struct Task {
    id: i64,
    title: String,
    done: bool,
    priority: u8,
}

fn find(tasks: &mut [Task], id: i64) -> Option<&mut Task> {
    tasks.iter_mut().find(|task| task.id == id)
}

/// Tasks in priority order, ascending, ties broken by id ascending.
fn in_priority_order(tasks: &[Task]) -> Vec<&Task> {
    let mut ordered: Vec<&Task> = tasks.iter().collect();
    ordered.sort_by_key(|task| (task.priority, task.id));
    ordered
}

fn main() {
    let path = env::args().nth(1).expect("a command file");
    let text = fs::read_to_string(&path).expect("a readable command file");
    let mut tasks: Vec<Task> = Vec::new();
    let mut next_id = 1;

    for line in text.trim_end_matches('\n').split('\n') {
        if line.is_empty() {
            continue;
        }
        let (command, rest) = match line.split_once(' ') {
            Some((command, rest)) => (command, rest),
            None => (line, ""),
        };

        if command == "add" {
            tasks.push(Task {
                id: next_id,
                title: rest.to_string(),
                done: false,
                priority: DEFAULT_PRIORITY,
            });
            println!("added {}", next_id);
            next_id += 1;
        } else if command == "done" {
            let id: i64 = rest.parse().expect("a task id");
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(task) => {
                    task.done = true;
                    println!("done {}", id);
                }
            }
        } else if command == "prio" {
            let (id, priority) = match rest.split_once(' ') {
                Some((id, priority)) => (id, priority),
                None => (rest, ""),
            };
            let id: i64 = id.parse().expect("a task id");
            let valid = priority.len() == 1 && priority.bytes().all(|b| b.is_ascii_digit());
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(_) if !valid => println!("bad priority {}", priority),
                Some(task) => {
                    task.priority = priority.as_bytes()[0] - b'0';
                    println!("prio {} {}", id, task.priority);
                }
            }
        } else if command == "list" && rest == "all" {
            for task in in_priority_order(&tasks) {
                let mark = if task.done { "x" } else { "-" };
                println!("{} {} {}", mark, task.id, task.title);
            }
        } else if command == "list" {
            for task in in_priority_order(&tasks).into_iter().filter(|task| !task.done) {
                println!("{} {}", task.id, task.title);
            }
        } else {
            println!("? {}", command);
        }
    }
}

